export default `\
#version 300 es
#define SHADER_NAME arc-trips-layer-fragment-shader

precision highp float;

in vec4 vColor;
in vec2 uv;
in float isValid;
in float vTime;

out vec4 fragColor;

void main(void) {
  if (isValid == 0.0) {
    discard;
  }

  fragColor = vColor;
  geometry.uv = uv;

  // 计算移动圆点效果
  float animationEffect = 1.0;
  
  if (arcTrips.fadeTrail) {
    // 计算动画周期：使用 trailLength 作为一个完整动画周期
    // 使用 mod 让 currentTime 在周期内循环，实现不间断的尾迹效果
    float animationCycle = arcTrips.trailLength;
    float cyclicTime = mod(arcTrips.currentTime * arcTrips.animationSpeed, animationCycle);
    
    // 计算圆点在弧线上的位置（0到1之间，0是起点，1是终点）
    float dotPosition = cyclicTime / animationCycle;
    
    // 当前片段在弧线上的位置（基于uv.x，范围是0到1）
    float segmentPosition = uv.x;
    
    if (arcTrips.showFullArc) {
      // 显示完整弧线，但添加移动圆点效果
      
      // 计算圆点与当前片段的距离
      float distanceToDot = abs(segmentPosition - dotPosition);
      
      // 使用 uniform 中的圆点大小
      float dotSize = arcTrips.dotSize;
      
      // 圆点效果：在圆点位置附近高亮
      if (distanceToDot < dotSize) {
        // 圆点内部：高亮度
        float dotIntensity = 1.0 - (distanceToDot / dotSize);
        dotIntensity = smoothstep(0.0, 1.0, dotIntensity);
        animationEffect = dotIntensity;
      } else {
        // 圆点外部：基础亮度
        animationEffect = 0.3;
      }
      
      // 添加尾迹效果：在圆点后面创建渐变尾迹
      float trailStart = dotPosition - arcTrips.dotTrailLength;
      float trailEnd = dotPosition;
      
      // 处理尾迹可能跨越起点的情况（循环）
      if (trailStart < 0.0) {
        // 尾迹跨越起点
        if (segmentPosition >= trailStart + 1.0 || segmentPosition <= trailEnd) {
          float normalizedPos;
          if (segmentPosition >= trailStart + 1.0) {
            normalizedPos = segmentPosition - 1.0;
          } else {
            normalizedPos = segmentPosition;
          }
          // 反转渐变方向：头部（dotPosition）深色，尾部（trailStart）淡色
          float trailProgress = (dotPosition - normalizedPos) / arcTrips.dotTrailLength;
          // 使用更陡峭的指数衰减，让渐变更明显
          float trailIntensity = exp(-trailProgress * 5.0);
          animationEffect = max(animationEffect, trailIntensity);
        }
      } else {
        // 尾迹不跨越起点
        if (segmentPosition >= trailStart && segmentPosition <= trailEnd) {
          // 反转渐变方向：头部（dotPosition）深色，尾部（trailStart）淡色
          float trailProgress = (dotPosition - segmentPosition) / arcTrips.dotTrailLength;
          // 使用更陡峭的指数衰减，让渐变更明显
          float trailIntensity = exp(-trailProgress * 5.0);
          animationEffect = max(animationEffect, trailIntensity);
        }
      }
      
    } else {
      // 只显示移动圆点和尾迹部分
      float distanceToDot = abs(segmentPosition - dotPosition);
      float dotSize = arcTrips.dotSize;
      
      animationEffect = 0.0;
      
      // 圆点效果
      if (distanceToDot < dotSize) {
        float dotIntensity = 1.0 - (distanceToDot / dotSize);
        dotIntensity = smoothstep(0.0, 1.0, dotIntensity);
        animationEffect = dotIntensity;
      }
      
      // 尾迹效果
      float trailStart = dotPosition - arcTrips.dotTrailLength;
      float trailEnd = dotPosition;
      
      if (trailStart < 0.0) {
        // 尾迹跨越起点
        if (segmentPosition >= trailStart + 1.0 || segmentPosition <= trailEnd) {
          float normalizedPos;
          if (segmentPosition >= trailStart + 1.0) {
            normalizedPos = segmentPosition - 1.0;
          } else {
            normalizedPos = segmentPosition;
          }
          // 反转渐变方向：头部（dotPosition）深色，尾部（trailStart）淡色
          float trailProgress = (dotPosition - normalizedPos) / arcTrips.dotTrailLength;
          // 使用更陡峭的指数衰减，让渐变更明显
          float trailIntensity = exp(-trailProgress * 5.0);
          animationEffect = max(animationEffect, trailIntensity);
        }
      } else {
        // 尾迹不跨越起点
        if (segmentPosition >= trailStart && segmentPosition <= trailEnd) {
          // 反转渐变方向：头部（dotPosition）深色，尾部（trailStart）淡色
          float trailProgress = (dotPosition - segmentPosition) / arcTrips.dotTrailLength;
          // 使用更陡峭的指数衰减，让渐变更明显
          float trailIntensity = exp(-trailProgress * 5.0);
          animationEffect = max(animationEffect, trailIntensity);
        }
      }
    }
  }

  // 应用动画效果到颜色
  fragColor.a *= animationEffect;

  DECKGL_FILTER_COLOR(fragColor, geometry);
}
`;
